    ('19ed3a0f-09e5-4844-ae5d-9d50bea1371b'::uuid, 'card_description', 'A large bearded man wears a black cloak in the best-known painting of this cave. Known as Painting 1, the figure also has a striped tunic and an elaborate headpiece.', 'In the Grottos of Juxtlahuaca, painted walls show a large bearded man in a black cloak and a red Feathered Serpent with green plumes. A dozen skeletons were found in the Hall of the Dead.', 'teaser-card-s044-rollback:19ed3a0f-09e5-4844-ae5d-9d50bea1371b:card_description', 'rollback of teaser-card-s044: card_description ''In the Grottos of Juxtlahuaca, painted walls show a large bearded man in a black cloak and a red Feathered Serpent with green plumes. A dozen skeletons were found in the Hall of the Dead.'' restored on Grottos of Juxtlahuaca', '95e0f3ced394a7a60bbabdd8600343c673de2e97c7ce086420e5ddc9ed4f56f1|4905352496e99982e3c99ba9fd39ffa9a2c7ebc660f2a07cf92a757dbd313f5f|4905352496e99982e3c99ba9fd39ffa9a2c7ebc660f2a07cf92a757dbd313f5f', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A large bearded man wears a black cloak in the best-known painting of this cave. Known as Painting 1, the figure also has a striped tunic and an elaborate headpiece."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the site is a cave with cave art [S1]; its best-known painting is called Painting 1 [S1]; the painting shows a large bearded man [S1]; the man wears a black cloak [S1]; the figure has a striped tunic [S1]; the figure has an elaborate headpiece [S1]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A large bearded man wears a black cloak in the best-known painting of this cave [SUPPORTED: https://es.wikipedia.org/wiki/Grutas_de_Juxtlahuaca]; The painting is the best-known painting of the cave [SUPPORTED: https://es.wikipedia.org/wiki/Grutas_de_Juxtlahuaca]; The man in the painting is large [SUPPORTED: https://www.antiquity.ac.uk/projgall/coe305]; The man in the painting is bearded [SUPPORTED: https://www.antiquity.ac.uk/projgall/coe305]; The man wears a black cloak [SUPPORTED: https://www.antiquity.ac.uk/projgall/coe305]; The painting is known as Painting 1 [SUPPORTED: https://es.wikipedia.org/wiki/Grutas_de_Juxtlahuaca]; The figure has a striped tunic [SUPPORTED: https://www.antiquity.ac.uk/projgall/coe305]; The figure has an elaborate headpiece [SUPPORTED: https://es.wikipedia.org/wiki/Grutas_de_Juxtlahuaca]"}]'::jsonb),
    ('1ac14890-b87e-43e5-a108-57fc4c51c6b2'::uuid, 'card_description', 'Nature, not human hands, made these dramatic rock formations along a river. Their densest stretch lies between two villages, and in 2012 their park joined the UNESCO World Heritage List.', 'Natural rock pillars 150 to 300 metres high, formed during the Cambrian Period over 500 million years ago. Fossils from that era are embedded throughout the formation.', 'teaser-card-s044-rollback:1ac14890-b87e-43e5-a108-57fc4c51c6b2:card_description', 'rollback of teaser-card-s044: card_description ''Natural rock pillars 150 to 300 metres high, formed during the Cambrian Period over 500 million years ago. Fossils from that era are embedded throughout the formation.'' restored on Pilares do Lena', 'c3a6f24e2c07abf7e24191fe420ee6efa06e622724fa30adb67fcda1649a713c|a3b1ca023cf1745c80e809e3efca74036145c52ba9b64dbf7b3c04a8c76c9ec4|a3b1ca023cf1745c80e809e3efca74036145c52ba9b64dbf7b3c04a8c76c9ec4', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Nature, not human hands, made these dramatic rock formations along a river. Their densest stretch lies between two villages, and in 2012 their park joined the UNESCO World Heritage List."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the formations are natural, not made by people [S1]; they are dramatic rock formations [S1]; they stand along a river [S1]; their highest concentration lies between two villages [S2]; their nature park was inscribed on the UNESCO World Heritage List in 2012 [S3]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "These are dramatic rock formations along a river. [SUPPORTED: https://ru.wikipedia.org/wiki/%D0%9B%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B5_%D1%81%D1%82%D0%BE%D0%BB%D0%B1%D1%8B]; Nature, not human hands, made these rock formations. [SUPPORTED: https://ru.wikipedia.org/wiki/%D0%9B%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B5_%D1%81%D1%82%D0%BE%D0%BB%D0%B1%D1%8B]; Their densest stretch lies between two villages. [SUPPORTED: https://www.vpoxod.ru/page/toponym/lenskie_stolby_info]; The rock formations have a park of their own. [SUPPORTED: https://ru.wikipedia.org/wiki/%D0%9B%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B5_%D1%81%D1%82%D0%BE%D0%BB%D0%B1%D1%8B]; In 2012 their park joined the UNESCO World Heritage List. [SUPPORTED: https://ru.wikipedia.org/wiki/%D0%9B%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B5_%D1%81%D1%82%D0%BE%D0%BB%D0%B1%D1%8B]"}]'::jsonb),
    ('3b2e39f0-6ca3-4905-8a23-f118b7ae632a'::uuid, 'card_description', 'A unique leaning column marks the T-shaped monument of this settlement. Pillared rooms and sections of defensive walls stand here too, under a UNESCO World Heritage listing.', 'A Talayotic village with a table sanctuary, necropolis of artificial burial caves, and stone-roofed rooms with columns. The "table" is a T-shaped stone unique to Menorca.', 'teaser-card-s044-rollback:3b2e39f0-6ca3-4905-8a23-f118b7ae632a:card_description', 'rollback of teaser-card-s044: card_description ''A Talayotic village with a table sanctuary, necropolis of artificial burial caves, and stone-roofed rooms with columns. The "table" is a T-shaped stone unique to Menorca.'' restored on Poblat Talaiòtic de Talatí de Dalt', 'e75e7ba7f3b6e376d2c70a40f541922e33362eaa8613947818059f81cfc92506|3e6a596c2e5fd0f8d9237813bbf2650e6052a1495403d5989afa59734368f410|3e6a596c2e5fd0f8d9237813bbf2650e6052a1495403d5989afa59734368f410', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A unique leaning column marks the T-shaped monument of this settlement. Pillared rooms and sections of defensive walls stand here too, under a UNESCO World Heritage listing."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the site is a settlement [S1]; it has a T-shaped monument [S2]; the T-shaped monument has a unique leaning column [S2]; it has pillared (hypostyle) rooms [S2]; it has sections of defensive walls [S2]; it falls under a UNESCO World Heritage listing [S2]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A leaning column marks the T-shaped monument of this settlement. [SUPPORTED: https://www.menorcatalayotica.info/en/Talayotic_Settlement_of_Talati_/10675]; The leaning column is unique. [SUPPORTED: https://www.menorcatalayotica.info/en/Talayotic_Settlement_of_Talati_/10675]; The settlement has a T-shaped monument. [SUPPORTED: https://www.illesbalears.travel/en/menorca/talaiot-talati-de-dalt]; The site is a settlement. [SUPPORTED: https://www.menorcatalayotica.info/en/Talayotic_Settlement_of_Talati_/10675]; Pillared rooms stand here too. [SUPPORTED: https://www.menorcatalayotica.info/en/Talayotic_Settlement_of_Talati_/10675]; Sections of defensive walls stand here too. [SUPPORTED: https://www.calamenorca.com/talati-de-dalt/]; The site stands under a UNESCO World Heritage listing. [SUPPORTED: https://es.wikipedia.org/wiki/Talat%C3%AD_de_Dalt]"}]'::jsonb),
    ('4a87bc78-0813-4110-aa1e-3818326bee00'::uuid, 'card_description', 'One cave gives its name to a whole protected zone of archaeology. On Tenerife, one of the Canary Islands, that cave in the island''s north counts as an important site for archaeology.', 'Atop a cliff in the north of Tenerife lay a village of natural caves and huts. At the Cave of the Guanches, ceramics found inside have been dated to the 6th century BCE.', 'teaser-card-s044-rollback:4a87bc78-0813-4110-aa1e-3818326bee00:card_description', 'rollback of teaser-card-s044: card_description ''Atop a cliff in the north of Tenerife lay a village of natural caves and huts. At the Cave of the Guanches, ceramics found inside have been dated to the 6th century BCE.'' restored on Cave of the Guanches', '0618d3a5b40d4f795a937e197b8f5f47f9912ba5ad63d2735c6d8ea030557112|d3a86243e10f6223901b924c3fb3dd39614d9101790e47a81d6c92cb48632b4a|d3a86243e10f6223901b924c3fb3dd39614d9101790e47a81d6c92cb48632b4a', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "One cave gives its name to a whole protected zone of archaeology. On Tenerife, one of the Canary Islands, that cave in the island''s north counts as an important site for archaeology."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "a cave gives its name to a protected archaeological zone [S1, S2]; the protected zone revolves around that cave [S2]; the cave lies on Tenerife [S1]; Tenerife is one of the Canary Islands [S1]; the cave lies in the north of the island [S1]; it is an important archaeological site [S1]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "One cave gives its name to a whole protected zone of archaeology. [SUPPORTED: https://www.gobiernodecanarias.org/boc/2005/124/010.html]; The zone is protected. [SUPPORTED: https://www.gobiernodecanarias.org/boc/2005/124/010.html]; The cave is on Tenerife. [SUPPORTED: https://www.gobiernodecanarias.org/boc/2005/124/010.html]; Tenerife is one of the Canary Islands. [SUPPORTED: https://en.wikipedia.org/wiki/Tenerife]; The cave lies in the island''s north. [SUPPORTED: https://www.gobiernodecanarias.org/boc/2005/124/010.html]; The cave counts as an important site for archaeology. [SUPPORTED: https://es.wikipedia.org/wiki/Cueva_de_los_Guanches]"}]'::jsonb),
    ('54782fbd-0ba3-4673-941a-3f5cf1fc8290'::uuid, 'card_description', 'Ploughing disturbed remains, and digging began at an Anglo-Saxon cemetery. Three burial areas lie on the hill: along its crest, on its western slope, and cremations on the eastern slope.', 'Ploughing disturbed remains on Welbeck Hill; excavations began in 1962 at an Anglo-Saxon cemetery: burials along the hill crest, cremations on the eastern slope, 76 graves by July 1976.', 'teaser-card-s044-rollback:54782fbd-0ba3-4673-941a-3f5cf1fc8290:card_description', 'rollback of teaser-card-s044: card_description ''Ploughing disturbed remains on Welbeck Hill; excavations began in 1962 at an Anglo-Saxon cemetery: burials along the hill crest, cremations on the eastern slope, 76 graves by July 1976.'' restored on Welbeck Hill', 'a009ba7cd84dda637c0c8c8e8af6d3213bb5b84a91623aaba4e4341da40e77d0|bc435fedaa03f0f10da1d480b9493ee92a6600eea63df37b1856ed3747611e07|bc435fedaa03f0f10da1d480b9493ee92a6600eea63df37b1856ed3747611e07', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Ploughing disturbed remains, and digging began at an Anglo-Saxon cemetery. Three burial areas lie on the hill: along its crest, on its western slope, and cremations on the eastern slope."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "ploughing disturbed remains [S1]; excavation began after the ploughing disturbed the remains [S1]; the site is an Anglo-Saxon cemetery [S1]; three burial areas have been identified [S2]; the burial areas lie on a hill [S2]; one burial area runs along the hill crest [S2]; one burial area lies on the hill''s western slope [S2]; a deposit of cremations lies on the eastern slope [S2]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "There is an Anglo-Saxon cemetery here. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]; The cemetery lies on a hill. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]; Ploughing disturbed remains. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]; Digging began at the cemetery after ploughing disturbed remains. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]; Three burial areas lie on the hill. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]; One burial area lies along the hill''s crest. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]; One burial area lies on the hill''s western slope. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]; Cremations lie on the hill''s eastern slope. [SUPPORTED: https://northlincolnshiremuseum.co.uk/discover/welbeck-hill-anglo-saxon-cemetery/]"}]'::jsonb),
    ('5668cd67-4c06-4795-93f6-5c223e748ba7'::uuid, 'card_description', 'About 2,300 documented figures, mostly deer, are cut into the rock beside a strait. The motifs of this rock art site may stand for fertility, or for life, death and rebirth.', 'One of Northern Europe''s largest rock carving sites with over 2,000 petroglyphs, carved 4000–2000 BC along the Frøysjøen strait. Accessible only by boat or a 5 km hike through remote coastline.', 'teaser-card-s044-rollback:5668cd67-4c06-4795-93f6-5c223e748ba7:card_description', 'rollback of teaser-card-s044: card_description "One of Northern Europe''s largest rock carving sites with over 2,000 petroglyphs, carved 4000–2000 BC along the Frøysjøen strait. Accessible only by boat or a 5 km hike through remote coastline." restored on Rock Carvings at Vingen', '3f47cbb793e7457742acaee1c03e7c11ea669be2a505313df16fb191c6bb83ba|d57563411128a371234a3d607b458006d9cc2b5c2998b32eaba570eda96007b5|d57563411128a371234a3d607b458006d9cc2b5c2998b32eaba570eda96007b5', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "About 2,300 documented figures, mostly deer, are cut into the rock beside a strait. The motifs of this rock art site may stand for fertility, or for life, death and rebirth."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the site has about 2,300 documented figures [S2]; the figures are mostly deer [S2]; the figures are cut into the rock (a rock carving / rock art site) [S1]; the site lies beside a strait [S1]; the motifs may stand for fertility [S3]; the motifs may stand for life, death and rebirth [S3]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "About 2,300 documented figures are cut into the rock at this site. [SUPPORTED: https://www.bradshawfoundation.com/rockartnetwork/world_sites_watch/vingen/history_of_vingen_rock_art.php]; The figures are mostly deer. [SUPPORTED: https://www.kringom.no/en/vingen-rock-carving-site]; The figures are cut into the rock. [SUPPORTED: https://www.kringom.no/en/vingen-rock-carving-site]; The figures lie beside a strait. [SUPPORTED: https://no.wikipedia.org/wiki/Vingenfeltet]; The water the figures lie beside (Frøysjøen) is a strait. [SUPPORTED: https://en.wikipedia.org/wiki/Fr%C3%B8ysj%C3%B8en]; This is a rock art site. [SUPPORTED: https://www.kringom.no/en/vingen-rock-carving-site]; The motifs may stand for fertility. [SUPPORTED: https://www.kringom.no/en/vingen-rock-carving-site]; The motifs may stand for life, death and rebirth. [SUPPORTED: https://www.kringom.no/en/vingen-rock-carving-site]"}]'::jsonb),
    ('56f594fc-6819-4d51-98a4-1cf5b4a265a6'::uuid, 'card_description', 'Lead question tablets recovered here date from the 6th to 2nd centuries BC. King Pyrrhus made the place his religious capital, and its Naia festival featured athletic and dramatic contests.', 'Active since 1500 BC — centuries before Delphi rose to fame — this oracle sanctuary''s pilgrims scratched questions on lead tablets; priests read the answers in the rustling of a sacred oak.', 'teaser-card-s044-rollback:56f594fc-6819-4d51-98a4-1cf5b4a265a6:card_description', 'rollback of teaser-card-s044: card_description "Active since 1500 BC — centuries before Delphi rose to fame — this oracle sanctuary''s pilgrims scratched questions on lead tablets; priests read the answers in the rustling of a sacred oak." restored on Archaeological Site of Dodoni', 'a0ea3949ad8e130563c416cc20bf77dffe47d67e05af4385302756b2c4f588ac|4beabcceb8f988f9ac6b73ccf98c922c5a661d4c046e305deba1a6c51f875c34|4beabcceb8f988f9ac6b73ccf98c922c5a661d4c046e305deba1a6c51f875c34', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Lead question tablets recovered here date from the 6th to 2nd centuries BC. King Pyrrhus made the place his religious capital, and its Naia festival featured athletic and dramatic contests."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "lead question-tablets have been recovered at the site [S2]; the tablets date from the 6th to 2nd centuries BC [S2]; King Pyrrhus made the place his religious capital [S3]; a festival called the Naia was held there [S4]; the Naia festival featured athletic and dramatic contests [S4]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Lead question tablets were recovered here [SUPPORTED: https://www.greeknewsagenda.gr/ancient-voices-on-lead-the-tablets-of-the-dodona-oracle-and-the-timeless-search-for-answers-to-human-concerns/]; The tablets are made of lead [SUPPORTED: https://www.archaeology.wiki/blog/2023/05/29/lead-tablets-of-dodona-in-the-memory-of-the-world-of-unesco/]; The tablets carry questions [SUPPORTED: https://www.archaeology.wiki/blog/2023/05/29/lead-tablets-of-dodona-in-the-memory-of-the-world-of-unesco/]; The tablets date from the 6th to 2nd centuries BC [SUPPORTED: https://www.archaeology.wiki/blog/2023/05/29/lead-tablets-of-dodona-in-the-memory-of-the-world-of-unesco/]; King Pyrrhus made the place his religious capital [SUPPORTED: https://www.worldhistory.org/Dodona/]; The place had its own Naia festival [SUPPORTED: https://www.worldhistory.org/Dodona/]; The Naia festival featured athletic contests [SUPPORTED: http://ancienttheater.culture.gr/en/ekpaideftikoyliko/entupa/follow-me-to-the-ancient-theatrs-odeia-1/61-follow-me-dodona-1/file]; The Naia festival featured dramatic contests [SUPPORTED: http://ancienttheater.culture.gr/en/ekpaideftikoyliko/entupa/follow-me-to-the-ancient-theatrs-odeia-1/61-follow-me-dodona-1/file]"}]'::jsonb),
    ('758dd394-0b33-4f82-821d-5b6de5058afe'::uuid, 'card_description', 'A ring of 56 chalk pits dates to the monument''s earliest phases. The pits belong to the late fourth and early third millennium BC, and are named after an antiquarian.', 'At Stonehenge, a ring of 56 chalk pits, the Aubrey Holes, dates to its earliest phases. 25 of them later held cremation burials, making Stonehenge Britain''s oldest cremation cemetery.', 'teaser-card-s044-rollback:758dd394-0b33-4f82-821d-5b6de5058afe:card_description', 'rollback of teaser-card-s044: card_description "At Stonehenge, a ring of 56 chalk pits, the Aubrey Holes, dates to its earliest phases. 25 of them later held cremation burials, making Stonehenge Britain''s oldest cremation cemetery." restored on Aubrey Holes - Stonehenge', '28ad5153f52e2977863d5b8e72b99fbd18a186c0e62a621a09597d75e5995ec8|265e7b1c4fff6c1ff7b992203fb283b1048e2d5227d136de23f923d1b677a19d|265e7b1c4fff6c1ff7b992203fb283b1048e2d5227d136de23f923d1b677a19d', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A ring of 56 chalk pits dates to the monument''s earliest phases. The pits belong to the late fourth and early third millennium BC, and are named after an antiquarian."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the site is a ring of chalk pits [S1]; the ring has 56 pits [S1]; the pits date to the monument''s earliest phases [S2]; the pits date to the late fourth and early third millennium BC [S2]; the pits are named after an antiquarian [S1]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "The pits form a ring at Stonehenge. [SUPPORTED: https://www.berksarch.co.uk/index.php/bluestones-and-white-bones-the-origins-of-the-people-buried-at-stonehenge/]; There are 56 pits. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/]; The pits are chalk pits. [SUPPORTED: https://www.berksarch.co.uk/index.php/bluestones-and-white-bones-the-origins-of-the-people-buried-at-stonehenge/]; The ring dates to the monument''s earliest phases. [SUPPORTED: https://www.berksarch.co.uk/index.php/bluestones-and-white-bones-the-origins-of-the-people-buried-at-stonehenge/]; The pits belong to the late fourth and early third millennium BC. [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]; The pits are named after an antiquarian. [SUPPORTED: https://en.wikipedia.org/wiki/John_Aubrey]; The man they are named after was an antiquarian. [SUPPORTED: https://en.wikipedia.org/wiki/John_Aubrey]"}]'::jsonb),
    ('a4ac2a6f-0159-447e-a6d2-7300fbc986ef'::uuid, 'card_description', 'The first Neanderthal Y chromosome to be sequenced came from this cave. Researchers recovered more than 2500 hominin fossil pieces here, from at least 13 individuals.', 'The first sequencing of the Neanderthal Y chromosome was successfully completed from a specimen from Sidrón Cave.', 'teaser-card-s044-rollback:a4ac2a6f-0159-447e-a6d2-7300fbc986ef:card_description', 'rollback of teaser-card-s044: card_description ''The first sequencing of the Neanderthal Y chromosome was successfully completed from a specimen from Sidrón Cave.'' restored on Sidrón Cave', '92cf7a44f549f4ce1fbb1e0fd0f5239efdd5524e41f0906d2aaf118c303e8328|eca7b117be3c2d521e08f35843d7bcd0abecac58d4dde9e8274df982a2ee4aed|eca7b117be3c2d521e08f35843d7bcd0abecac58d4dde9e8274df982a2ee4aed', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "The first Neanderthal Y chromosome to be sequenced came from this cave. Researchers recovered more than 2500 hominin fossil pieces here, from at least 13 individuals."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the first Neanderthal Y chromosome to be sequenced came from a specimen from this site [S3]; the site is a cave [S2, S3]; researchers recovered more than 2500 hominin fossil pieces here [S1]; the fossils come from at least 13 individuals [S2]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A Neanderthal Y chromosome was sequenced from a specimen from this cave [SUPPORTED: https://www.sci.news/genetics/analysis-neanderthal-y-chromosome-03766.html]; It was the first Neanderthal Y chromosome to be sequenced [SUPPORTED: https://www.sci.news/genetics/analysis-neanderthal-y-chromosome-03766.html]; Researchers recovered more than 2500 hominin fossil pieces here [SUPPORTED: https://www.nature.com/articles/s41598-019-38571-1]; The fossil pieces come from at least 13 individuals [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0062797]"}]'::jsonb),
    ('b656d341-6132-4601-a0d3-386e7e725b6f'::uuid, 'card_description', 'Digging before 500 new houses were built uncovered a previously unknown site. It holds a Bronze Age landscape and an extensive medieval structure with floor tiles like Glastonbury Abbey''s.', 'Before 500 new houses were built near Wellington, digs in 2013 found the unknown Longforth Farm: stone foundations around courtyards, their decorated floor tiles like Glastonbury Abbey''s.', 'teaser-card-s044-rollback:b656d341-6132-4601-a0d3-386e7e725b6f:card_description', 'rollback of teaser-card-s044: card_description "Before 500 new houses were built near Wellington, digs in 2013 found the unknown Longforth Farm: stone foundations around courtyards, their decorated floor tiles like Glastonbury Abbey''s." restored on Longforth Farm', 'dbf52f3f9f189fa19289800d71af7e3213dcf43ab915a1842743432fc22db9c0|1463611f0559aed5b9c3edbbfd32f76ec1607a1a211ee1edc21964b2f9373a3b|1463611f0559aed5b9c3edbbfd32f76ec1607a1a211ee1edc21964b2f9373a3b', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Digging before 500 new houses were built uncovered a previously unknown site. It holds a Bronze Age landscape and an extensive medieval structure with floor tiles like Glastonbury Abbey''s."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the site was uncovered by excavation [S2]; the excavation took place before the building of 500 new houses [S2]; the site was previously unknown [S2]; the site holds a Bronze Age landscape [S1]; the site holds an extensive medieval structure [S1]; the floor tiles found there are similar to those at Glastonbury Abbey [S4]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Digging before new houses were built uncovered a previously unknown site [SUPPORTED: https://www.wessexarch.co.uk/our-work/longforth-farm]; The development was of 500 new houses [SUPPORTED: https://archaeology.co.uk/articles/discovering-longforth-farm.htm]; It holds a Bronze Age landscape [SUPPORTED: https://www.wessexarch.co.uk/our-work/longforth-farm]; It holds an extensive medieval structure [SUPPORTED: https://www.wessexarch.co.uk/our-work/longforth-farm]; The medieval structure is still held at the site (present tense: not built over by the houses) [SUPPORTED: https://archaeology.co.uk/articles/discovering-longforth-farm.htm]; The medieval structure has floor tiles like Glastonbury Abbey''s [SUPPORTED: https://www.wessexarch.co.uk/our-work/longforth-farm]"}]'::jsonb),
    ('c086510a-dc65-4f32-ae34-f86578bd7cdf'::uuid, 'card_description', 'Only one megalithic temple on these heights has remains that survived. The survivor is a complex of two temples, the larger with a concave facade and stone paving up to the central court.', 'On a plateau above the Grand Harbour, the Kordin Temples keep a stone-paved forecourt found in no other temple of Malta. The first part is believed to have been built around 3700 BC.', 'teaser-card-s044-rollback:c086510a-dc65-4f32-ae34-f86578bd7cdf:card_description', 'rollback of teaser-card-s044: card_description ''On a plateau above the Grand Harbour, the Kordin Temples keep a stone-paved forecourt found in no other temple of Malta. The first part is believed to have been built around 3700 BC.'' restored on Kordin Temples', 'c37e0aef1a9be4343c478d3efa6b157c95d47dc8c736360d433a520a8e0ad4d5|98e6bc508b2ed45539e8930b283b0078b23b5b42eb7f4efa5ab27a1453149dcf|98e6bc508b2ed45539e8930b283b0078b23b5b42eb7f4efa5ab27a1453149dcf', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Only one megalithic temple on these heights has remains that survived. The survivor is a complex of two temples, the larger with a concave facade and stone paving up to the central court."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "there were megalithic temples on these heights [S1]; only one temple on these heights has surviving remains [S2]; the surviving one is a complex of two temples [S3]; one of the two temples is the larger [S4]; the larger temple has a concave facade [S4, S5]; stone paving leads up to the central court [S5]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "Only one megalithic temple on these heights has remains that survived [SUPPORTED: https://heritagemalta.mt/explore/kordin-iii/]; These heights held more than one megalithic temple [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=10417]; The survivor''s remains survived (they still exist) [SUPPORTED: https://heritagemalta.mt/news/kordin-iii-temples-to-open-exclusively-for-heritage-malta-passport-visa-holders/]; The survivor is a complex of two temples [SUPPORTED: https://heritagemalta.mt/news/kordin-iii-temples-to-open-exclusively-for-heritage-malta-passport-visa-holders/]; One of the two temples is the larger (the other is smaller) [SUPPORTED: https://etd.ohiolink.edu/acprod/odb_etd/ws/send_file/send?accession=ucin1201462840&disposition=inline]; The larger temple has a concave facade [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=10417]; The larger temple has stone paving up to the central court [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=10417]"}]'::jsonb),
    ('e59e7ff4-2392-4365-ab67-2b7fc0d90472'::uuid, 'card_description', 'When the funerary slab was lifted, a large offering still sat in place. The slab lay in the lower chamber of a tomb whose remains, covered in cinnabar and hematite, were a woman''s.', 'Buried deep in the Late Classic Acropolis of Copán, the Margarita Tomb held a Maya woman''s remains covered in cinnabar and hematite, a vaulted stairway joining its upper and lower chambers.', 'teaser-card-s044-rollback:e59e7ff4-2392-4365-ab67-2b7fc0d90472:card_description', 'rollback of teaser-card-s044: card_description "Buried deep in the Late Classic Acropolis of Copán, the Margarita Tomb held a Maya woman''s remains covered in cinnabar and hematite, a vaulted stairway joining its upper and lower chambers." restored on Margarita Tomb', 'af2d7276ab040569d99283d5defa3c0d53925b2baf9fc7e8a4f5a93addcfcd46|939c0d627ffa13fb5db7f636639646e6c8a400f5680809a2f7c0d8137a4d309f|939c0d627ffa13fb5db7f636639646e6c8a400f5680809a2f7c0d8137a4d309f', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "When the funerary slab was lifted, a large offering still sat in place. The slab lay in the lower chamber of a tomb whose remains, covered in cinnabar and hematite, were a woman''s."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the site has a funerary slab [S3]; the funerary slab was lifted (removed) [S4]; when the slab was removed, an offering sat in its original position [S4]; the offering was large [S4]; the slab lay in the lower chamber [S3]; the site is a tomb with a lower chamber [S1, S2, S3]; remains were found in the tomb [S1]; the remains were covered in cinnabar and hematite [S1]; the remains were a woman''s, making it a woman''s tomb [S1]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "When the funerary slab was lifted, an offering sat under it [SUPPORTED: https://www.penn.museum/sites/expedition/the-margarita-tomb-at-copan-honduras/]; The offering still sat in place (in situ, undisturbed) [SUPPORTED: https://www.penn.museum/sites/expedition/the-margarita-tomb-at-copan-honduras/]; The funerary slab was lifted [SUPPORTED: https://www.penn.museum/sites/expedition/uncovering-copans-earliest-royal-tombs/]; The offering was a large one [SUPPORTED: https://www.penn.museum/sites/expedition/the-margarita-tomb-at-copan-honduras/]; The slab was a funerary slab, on which the remains lay [SUPPORTED: https://www.penn.museum/sites/expedition/uncovering-copans-earliest-royal-tombs/]; The tomb has a lower chamber (more than one chamber) [SUPPORTED: https://www.penn.museum/sites/expedition/the-margarita-tomb-at-copan-honduras/]; The slab lay in the lower chamber of the tomb [SUPPORTED: https://www.penn.museum/sites/expedition/the-margarita-tomb-at-copan-honduras/]; The tomb''s remains were covered in cinnabar [SUPPORTED: https://archive.archaeology.org/9607/newsbriefs/copan.html]; The tomb''s remains were covered in hematite [SUPPORTED: https://archive.archaeology.org/9607/newsbriefs/copan.html]; The remains were a woman''s [SUPPORTED: https://archive.archaeology.org/9607/newsbriefs/copan.html]"}]'::jsonb),
    ('eae0879c-2e4a-422d-8626-2fbf21adb227'::uuid, 'card_description', 'A second chamber, and perhaps a third, may exist within this chambered cairn. So believed the antiquary Erskine Beveridge of the Neolithic cairn on an island, entered from the east side.', 'On North Uist stands Barpa Langass, a Neolithic chambered cairn around 5,000 years old, roofed with massive slabs. Erskine Beveridge believed a second, perhaps a third, chamber exists.', 'teaser-card-s044-rollback:eae0879c-2e4a-422d-8626-2fbf21adb227:card_description', 'rollback of teaser-card-s044: card_description ''On North Uist stands Barpa Langass, a Neolithic chambered cairn around 5,000 years old, roofed with massive slabs. Erskine Beveridge believed a second, perhaps a third, chamber exists.'' restored on Barpa Langass', 'd5e4c26bf8dc868e9ff4f9a0d052bffa90294e41e94ea2be237d619041decf59|b17af668a08e2edba0709d2adffbb539c6df494e6f5fdb60f79c687f2be25938|b17af668a08e2edba0709d2adffbb539c6df494e6f5fdb60f79c687f2be25938', '[{"source": "lane WB run wb-shorts-d81-a1-2026-11-07: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A second chamber, and perhaps a third, may exist within this chambered cairn. So believed the antiquary Erskine Beveridge of the Neolithic cairn on an island, entered from the east side."}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "the site is a chambered cairn [S1]; a second chamber may exist within it, according to the belief of Erskine Beveridge [S3]; perhaps a third chamber exists as well, according to the same belief [S3]; Erskine Beveridge was an antiquary [S3]; the cairn is Neolithic [S1]; the cairn stands on an island [S1]; the cairn''s entrance is on the east side [S2]"}, {"source": "lane WB run wb-shorts-d81-a1-2026-11-07: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a1-2026-11-07/OUTCOMES.jsonl", "quote": "A second chamber may exist within this chambered cairn [SUPPORTED: https://portal.historicenvironment.scot/designation/SM892]; Perhaps a third chamber may exist within it [SUPPORTED: https://ceut.northernheritage.org/barpa-langass-pobull-fhinn/]; This was what the antiquary Erskine Beveridge believed of the cairn [UNVERIFIABLE, no proving quote: None]; Erskine Beveridge was an antiquary [SUPPORTED: https://en.wikipedia.org/wiki/Erskine_Beveridge]; It is a chambered cairn [SUPPORTED: https://portal.historicenvironment.scot/designation/SM892]; The cairn is Neolithic [SUPPORTED: https://hbsmrweb-westernisles.esdm.co.uk/Monument/MWE10236]; The cairn is on an island [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=516]; The cairn is entered from the east side [SUPPORTED: https://portal.historicenvironment.scot/designation/SM892]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 19;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s044-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s044-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s044-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 19 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s044-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s044-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
